<template>
  <Teleport to="body"><dialog ref="dialog" class="report-document-dialog" aria-labelledby="report-document-title" @close="emit('close')">
    <header><div><small>REPORT DOCUMENT</small><h2 id="report-document-title">报告正文</h2></div><button aria-label="关闭正文编辑" @click="dialog?.close()"><X :size="18" /></button></header>
    <div class="document-toolbar"><select v-model="selectedReport" aria-label="选择报告" @change="load"><option v-for="id in reportIds" :key="id" :value="id">{{ labels[id] || '历史报告' }}</option></select><button :class="{ active: advanced }" @click="advanced = !advanced">{{ advanced ? '返回正文' : '结构与样式' }}</button><button :disabled="busy" @click="exportDocument">导出当前版本</button></div>
    <p v-if="document" class="document-meta">正文版本 {{ document.revision }} · {{ document.items?.filter((b: any) => b.manualOverride).length || 0 }} 块手工修改 · 数据采集于 {{ document.dataAsOf ? new Date(document.dataAsOf).toLocaleString() : "历史快照" }}</p>
    <template v-if="advanced"><p>按操作合同批量编辑章节、表格、附件或排版。所有修改只影响当前报告。</p><textarea v-model="operationsText" class="operations-input" aria-label="正文操作 JSON" spellcheck="false" /><div class="document-actions"><button @click="showSchema">查看操作合同</button><button :disabled="busy" @click="applyAdvanced">应用操作</button></div><pre v-if="schemaText">{{ schemaText }}</pre></template>
    <template v-else-if="block">
      <div class="document-block-head"><select v-model.number="blockIndex" aria-label="选择正文块" @change="resetBlock"><option v-for="(item, index) in document.items" :key="item.id" :value="index">{{ item.content?.slice(0, 32) || ({ keyValueTable: '报告主体表格', table: '表格', attachment: '附件', pageBreak: '分页', list: '列表' } as any)[item.type] || '段落' }}</option></select><label><input v-model="draft.visible" type="checkbox" />显示本块</label></div>
      <div class="document-editor">
        <template v-if="draft.rows"><div v-for="row in visibleRows" :key="row.id" class="document-row"><textarea v-for="cell in row.cells" :key="cell.id" v-model="cell.content" :aria-label="`${row.id} ${cell.id}`" /><button aria-label="隐藏当前表格行" @click="hideRow(row.id)"><X :size="14" /></button></div><div class="document-pagination"><button :disabled="rowPage === 0" @click="rowPage--">上一页</button><span>{{ rowPage + 1 }} / {{ Math.max(1, Math.ceil(draft.rows.length / 5)) }}</span><button :disabled="(rowPage + 1) * 5 >= draft.rows.length" @click="rowPage++">下一页</button></div></template>
        <textarea v-else v-model="draft.content" class="document-content" aria-label="正文文字" />
      </div>
      <div class="document-actions"><button @click="addParagraph">添加段落</button><button v-if="block.manualOverride" @click="restoreAuto">恢复自动内容</button><button :disabled="busy" class="primary" @click="saveBlock">保存修改</button></div>
    </template>
    <p role="status" class="document-feedback">{{ message || '刷新数据会保留手工修改。导出使用当前正文版本，不重新联网采集。' }}</p>
  </dialog></Teleport>
</template>
<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { X } from '@/components/icons/lucide';
const props = defineProps<{ workspaceId: string; reportIds: string[] }>(); const emit = defineEmits<{ close: [] }>();
const dialog = ref<HTMLDialogElement>(); const selectedReport = ref(props.reportIds[0]); const document = ref<any>(); const labels = ref<Record<string, string>>({}); const blockIndex = ref(0); const rowPage = ref(0); const draft = ref<any>({}); const busy = ref(false); const message = ref(''); const advanced = ref(false); const schemaText = ref('');
const operationsText = ref('[\n  { "op": "insert_block", "block": { "id": "unresolved", "type": "paragraph", "content": "未解决问题：" } }\n]');
const block = computed(() => document.value?.items[blockIndex.value]); const visibleRows = computed(() => draft.value.rows?.slice(rowPage.value * 5, (rowPage.value + 1) * 5) || []);
const api = window.electronAPI.report;
async function call(name: string, args: any) { const result = await api.call(name, args); if (!result.ok) throw new Error(result.summary); return result; }
async function load() { try { const result = await call('report_read_document', { reportId: selectedReport.value, view: 'full', limit: 100 }); let cursor = result.data.nextCursor; while (cursor) { const page = await call('report_read_document', { reportId: selectedReport.value, revision: result.data.revision, view: 'full', limit: 100, cursor }); result.data.items.push(...page.data.items); cursor = page.data.nextCursor; } document.value = result.data; labels.value[selectedReport.value] = result.data.items.find((b: any) => b.id === 'title')?.content || selectedReport.value; blockIndex.value = Math.min(blockIndex.value, result.data.items.length - 1); resetBlock(); } catch (error: any) { message.value = error.message; } }
function resetBlock() { draft.value = JSON.parse(JSON.stringify(block.value || {})); draft.value.visible = draft.value.visible !== false; rowPage.value = 0; }
async function edit(operations: any[]) { busy.value = true; try { const context = await call('report_get_context', { workspaceId: props.workspaceId }); await call('report_edit_document', { workspaceId: props.workspaceId, expectedRevisions: context.revisions, requestId: crypto.randomUUID(), reportIds: [selectedReport.value], documentRevisions: [{ reportId: selectedReport.value, revision: document.value.revision }], operations }); message.value = '正文已保存'; await load(); } catch (error: any) { message.value = error.message; } finally { busy.value = false; } }
async function saveBlock() {
  const operations: any[] = [];
  if (draft.value.visible !== (block.value.visible !== false)) operations.push({ op: 'update_block', blockId: block.value.id, patch: { visible: draft.value.visible } });
  if (draft.value.rows) { for (const row of draft.value.rows) for (const cell of row.cells) { const before = block.value.rows.find((r: any) => r.id === row.id)?.cells.find((c: any) => c.id === cell.id); if (before?.content !== cell.content) operations.push({ op: 'set_cell', blockId: block.value.id, rowId: row.id, cellId: cell.id, patch: { content: cell.content } }); } }
  else if (draft.value.content !== block.value.content) operations.push({ op: 'update_block', blockId: block.value.id, patch: { content: draft.value.content || '' } });
  if (operations.length) await edit(operations);
}
const hideRow = (rowId: string) => edit([{ op: 'remove_row', blockId: block.value.id, rowId }]);
const restoreAuto = () => edit([{ op: 'restore_auto', blockId: block.value.id }]);
const addParagraph = () => edit([{ op: 'insert_block', afterId: block.value.id, block: { id: `paragraph-${crypto.randomUUID()}`, type: 'paragraph', content: '在这里填写新段落' } }]);
async function showSchema() { const result = await call('report_get_schema', { section: 'document' }); const full = await call('report_get_schema', { section: 'all' }); schemaText.value = JSON.stringify({ ...result.data, operations: full.data.documentOperations }, null, 2); }
async function applyAdvanced() { try { const operations = JSON.parse(operationsText.value); if (!Array.isArray(operations)) throw new Error('请填写操作数组'); await edit(operations); } catch (error: any) { message.value = error.message; } }
async function exportDocument() { busy.value = true; try { const context = await call('report_get_context', { workspaceId: props.workspaceId }); const accepted = await call('report_export', { workspaceId: props.workspaceId, expectedRevisions: context.revisions, requestId: crypto.randomUUID(), reports: [{ reportId: selectedReport.value, revision: document.value.revision }], format: 'docx' }); message.value = '正在导出当前正文'; let operation; do { await new Promise(resolve => setTimeout(resolve, 800)); operation = await call('report_get_operation', { operationId: accepted.operationId }); } while (['accepted', 'running'].includes(operation.status)); message.value = operation.status === 'completed' ? '当前正文已导出，可在最近生成中保存' : operation.data.summary; } catch (error: any) { message.value = error.message; } finally { busy.value = false; } }
onMounted(async () => { dialog.value?.showModal(); await load(); for (const id of props.reportIds) if (!labels.value[id]) { const item = await call('report_read_document', { reportId: id, view: 'blocks', blockIds: ['title'] }); labels.value[id] = item.data.items[0]?.content || '历史报告'; } });
</script>
<style scoped lang="scss">
.report-document-dialog { width: min(980px, calc(100vw - 40px)); max-height: calc(100vh - 40px); border: 1px solid #ddd; border-radius: 16px; padding: 26px; color: #222; background: white; overflow: auto; scrollbar-width: none; &::-webkit-scrollbar { display: none; } &::backdrop { background: #1117; backdrop-filter: blur(4px); } header { display: flex; justify-content: space-between; small { color: #888; font-size: 10px; letter-spacing: 2px; } h2 { margin: 5px 0 20px; font-size: 24px; font-weight: 550; } > button { border: 0; align-self: flex-start; } } button,select { border: 1px solid #ddd; border-radius: 6px; background: #fff; padding: 8px 12px; color: #333; font-size: 12px; cursor: pointer; &:hover { background: #f4f4f4; } &:disabled { opacity: .4; } } select { max-width: 65%; } textarea { box-sizing: border-box; width: 100%; resize: vertical; min-height: 62px; border: 1px solid #e2e2e2; background: #fafafa; color: #333; padding: 9px; font: 13px/1.6 inherit; scrollbar-width: none; &::-webkit-scrollbar { display: none; } &:focus { outline: 1px solid #888; } } p { font-size: 12px; line-height: 1.7; }.document-content { min-height: 240px; }.operations-input { min-height: 250px; font-family: monospace; } pre { max-height: 180px; overflow: auto; scrollbar-width: none; font-size: 11px; white-space: pre-wrap; } }
.document-toolbar,.document-block-head,.document-actions,.document-pagination { display: flex; gap: 8px; align-items: center; }.document-toolbar { padding-bottom: 14px; border-bottom: 1px solid #eee; select { margin-right: auto; } }.document-block-head { margin: 15px 0; justify-content: space-between; label { font-size: 12px; } }input[type=checkbox] { accent-color: #222; }.document-meta { color: #999; overflow-wrap: anywhere; }.document-row { display: flex; margin: 5px 0; gap: 5px; > button { align-self: center; border: 0; padding: 4px; } }.document-actions { justify-content: flex-end; margin-top: 18px; .primary { background: #222; color: white; } }.document-pagination { justify-content: center; padding: 12px; font-size: 12px; color: #888; }.document-feedback { color: #777; margin-bottom: 0; }
</style>
